export default function Modal() {
  return (
    <div className="modal-backdrop" role="presentation">
      <div className="modal-content" role="dialog" aria-modal="true" aria-labelledby="modal-title">
        <button className="modal-close" aria-label="Close modal">x</button>
      </div>
    </div>
  );
}

export default function Navigation({ onNavigate }) {
  return (
    <nav className="navigation">
      <ul className="nav-links">
        <li><button className="nav-link" aria-current="page" onClick={() => onNavigate('jobs')}>Jobs</button></li>
      </ul>
    </nav>
  );
}

function handleAssignJob(jobId, technicianId) {
  window.dispatchEvent(new CustomEvent('job-assigned', { detail: { jobId, technicianId } }));
}
